#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;
using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.EventSystems;using UnityEditor;using TMPro;using Mewgic.Core;using Mewgic.UI;
namespace Mewgic
{
    [DefaultExecutionOrder(-10000)] public sealed class Part11CProbe:MonoBehaviour
    {
        public static string Output="docs/ProductionReports/Part11C/";
        readonly List<string> checks=new List<string>(),errors=new List<string>(),warnings=new List<string>();readonly Dictionary<string,string> playerKeys=new Dictionary<string,string>();
        static Part11CProbe active;
        void Awake(){if(active!=null){Destroy(gameObject);return;}active=this;DontDestroyOnLoad(gameObject);foreach(var suffix in new[]{"",".backup",".corrupt"}){string k=GameplayProgress.StorageKey+suffix;playerKeys[k]=PlayerPrefs.HasKey(k)?PlayerPrefs.GetString(k):null;}GameplayProgress.UseTestProfile(new ProgressData{completedTutorials=new List<string>{PawGuide.BasicId}});GameplayLevelCatalog.ResetSelection();Application.logMessageReceived+=Log;}
        void Log(string m,string s,LogType t){if(t==LogType.Warning)warnings.Add(m);if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m);}
        void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add(label);}
        PrototypeApp App=>FindFirstObjectByType<PrototypeApp>();PawGuide Guide=>FindFirstObjectByType<PawGuide>();
        Puzzle Model=>(Puzzle)typeof(PrototypeApp).GetField("puzzle",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(App);
        int Selected=>(int)typeof(PrototypeApp).GetField("selected",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(App);
        string Board=>string.Join("|",Model.Export().Select(b=>string.Join(",",b)));
        void Tap(string name){var go=GameObject.Find(name);Check(go!=null,"Buton: "+name);go.GetComponent<Button>().onClick.Invoke();}
        string TopHit(string name)
        {
            var canvas=FindFirstObjectByType<Canvas>();var camera=Camera.main;var mode=canvas.renderMode;var oldCam=canvas.worldCamera;var target=camera.targetTexture;float distance=canvas.planeDistance;var rt=new RenderTexture(900,1600,24);
            try {camera.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();FindFirstObjectByType<GameplayPresentation>().Layout();Guide.SendMessage("LateUpdate");Canvas.ForceUpdateCanvases();var rect=GameObject.Find(name).GetComponent<RectTransform>();var point=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(camera,rect.TransformPoint(rect.rect.center))};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(point,hits);return hits.Count>0?hits[0].gameObject.name:"";}
            finally{camera.targetTexture=target;canvas.renderMode=mode;canvas.worldCamera=oldCam;canvas.planeDistance=distance;rt.Release();DestroyImmediate(rt);Canvas.ForceUpdateCanvases();FindFirstObjectByType<GameplayPresentation>().Layout();Guide.SendMessage("LateUpdate");}
        }

        IEnumerator Start(){var run=Run();string failure=null;while(true){bool more=false;object next=null;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception e){failure=e.ToString();}if(!more||failure!=null)break;yield return next;}bool intact=playerKeys.All(p=>p.Value==null?!PlayerPrefs.HasKey(p.Key):PlayerPrefs.HasKey(p.Key)&&PlayerPrefs.GetString(p.Key)==p.Value);Application.logMessageReceived-=Log;GameplayProgress.RestorePlayerProfile();GameplayLevelCatalog.ResetSelection();File.WriteAllText(Output+"TESTS.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{success=failure==null&&errors.Count==0&&intact,failure,checks,errors,warnings,playerSaveAndBackupIntact=intact,unity=Application.unityVersion},Newtonsoft.Json.Formatting.Indented));EditorApplication.isPlaying=false;}
        IEnumerator WaitGameplay(){float until=Time.realtimeSinceStartup+8;do{yield return null;}while((Guide==null||GameObject.Find("Bottle 1")==null)&&Time.realtimeSinceStartup<until);yield return null;}
        IEnumerator Run()
        {
            yield return WaitGameplay();yield return new WaitForSecondsRealtime(.25f);Check(!Guide.Visible,"Tamamlanmış öğretici otomatik açılmıyor");Check(TopHit("PawCatTouch")=="PawCatTouch","Kedi gerçek UI raycast hedefi / "+TopHit("PawCatTouch"));
            string initial=Board,save=JsonUtility.ToJson(GameplayProgress.Current.Snapshot);Tap("PawCatTouch");Check(Guide.State==PawGuide.Phase.Menu&&Guide.BlocksGameplayActions,"Tek dokunuş Pati Yardımı menüsünü açıyor");yield return new WaitForSecondsRealtime(.25f);
            foreach(var n in new[]{"PawHow","PawHint","PawBoosters","PawClose"})Check(GameObject.Find(n)!=null,"Dört menü seçeneği: "+n);
            float alpha=GameObject.Find("PawBubble").GetComponent<CanvasGroup>().alpha;for(int i=0;i<8;i++)Tap("PawCatTouch");Check(FindObjectsByType<PawGuide>(FindObjectsSortMode.None).Length==1&&GameObject.Find("PawBubble").GetComponent<CanvasGroup>().alpha==alpha,"Hızlı dokunuş tek menüyü korur; animasyonu tekrar başlatmaz");
            Check(TopHit("Bottle 1")=="PawMenuShield","Görünmez katman şişe dokunuşunu yakalıyor");Tap("Bottle 1");Tap("Bottle 3");foreach(BoosterKind k in Enum.GetValues(typeof(BoosterKind)))App.UseBooster(k);
            Check(Board==initial&&Model.Moves==0&&Selected<0&&JsonUtility.ToJson(GameplayProgress.Current.Snapshot)==save,"Menüde şişe ve güçlendirici işlemleri model/veri değiştirmiyor");
            foreach(int h in new[]{1600,1950,2000})Capture(Output+"PawMenu-"+h+".png",900,h,h==2000);
            Tap("PawHow");Check(Guide.State==PawGuide.Phase.General&&Guide.BlocksGameplayActions,"Nasıl Oynanır ilk kısa balonu açıyor");yield return new WaitForSecondsRealtime(.25f);Capture(Output+"HowToPlay-1600.png",900,1600);Tap("Bottle 1");Tap("Bottle 3");Check(Model.Moves==0,"Kural balonu açıkken hamle yok");Tap("PawNext");Check(Guide.State==PawGuide.Phase.General,"İkinci kısa kural balonu");Tap("PawNext");Check(Guide.State==PawGuide.Phase.Menu&&JsonUtility.ToJson(GameplayProgress.Current.Snapshot)==save,"Kural anlatımı menüye döner; oyun sıfırlanmaz");
            Tap("PawBoosters");Check(Guide.State==PawGuide.Phase.Boosters&&Guide.BlocksGameplayActions,"Mevcut menüden 11D rehberi açılır");yield return new WaitForSecondsRealtime(.25f);Capture(Output+"BoosterIntro-1600.png",900,1600);for(int i=0;i<4;i++)Tap("PawNext");Check(!Guide.Visible&&GameplayProgress.Current.TutorialCompleted(PawGuide.BoosterId)&&GameplayProgress.Current.Remaining(BoosterKind.Undo)==3&&GameplayProgress.Current.Remaining(BoosterKind.Hint)==3&&GameplayProgress.Current.Remaining(BoosterKind.ExtraBottle)==1&&GameplayProgress.Current.Remaining(BoosterKind.Shuffle)==1,"Dört güç rehberi hak tüketmeden tamamlanır");yield return new WaitForSecondsRealtime(.3f);Tap("PawCatTouch");
            int routed=0;Action open=()=>routed++;Guide.BoosterHelpRequested+=open;Tap("PawBoosters");Check(routed==1&&!Guide.Visible,"Mevcut dış rehber bağlantısı tek kez çağrılır");Guide.BoosterHelpRequested-=open;yield return new WaitForSecondsRealtime(.25f);
            Tap("PawCatTouch");Tap("PawClose");Tap("Bottle 1");Tap("Bottle 3");Check(Model.Moves==0,"Kapanışta dokunuş alttaki şişeye geçmiyor");yield return new WaitForSecondsRealtime(.3f);Check(GameObject.Find("PawMenuShield")==null,"Kapanınca dokunma katmanı serbest");
            Tap("Bottle 1");Check(Selected==0,"Şişe seçimi normal çalışıyor");Tap("PawCatTouch");yield return new WaitForSecondsRealtime(.25f);Tap("Bottle 3");Check(Selected==0&&Model.Moves==0,"Seçim sırasında yardım seçimi korur, aktarım yapmaz");Tap("Pause");Check(App.IsPaused&&!Guide.Visible,"Pause menüyü güvenli kapatıyor");Tap("PawCatTouch");Tap("Bottle 3");Check(!Guide.Visible&&Model.Moves==0,"Pause sırasında yardım/şişe girişi yok");Tap("Resume");yield return new WaitForSecondsRealtime(.3f);Tap("Bottle 3");Tap("PawCatTouch");Check(Model.Moves==1&&!Guide.Visible,"Aktarım sürerken yardım açılmıyor");yield return new WaitForSecondsRealtime(1.1f);
            Tap("PawCatTouch");Check(Guide.State==PawGuide.Phase.Menu&&Model.Moves==1,"Oyun ortasında yardım açılır");Tap("PawClose");yield return new WaitForSecondsRealtime(.3f);Tap("Restart");
            Tap("PawCatTouch");int hints=GameplayProgress.Current.Remaining(BoosterKind.Hint);initial=Board;Tap("PawHint");yield return new WaitForSecondsRealtime(.25f);Check(!Guide.Visible&&Board==initial&&Model.Moves==0&&GameplayProgress.Current.Remaining(BoosterKind.Hint)==hints-1,"Hamle Öner mevcut Hint hakkından bir tane kullanır; veriyi değiştirmez");Check(FindObjectsByType<HintCueGraphic>(FindObjectsSortMode.None).Length==2,"Kaynak ve hedef metinsiz görsel işaretli");Check(!FindObjectsByType<TMP_Text>(FindObjectsSortMode.None).Any(t=>t.text.Contains("Altın kaynak")||t.text.Contains("mavi hedef")||t.text.Contains("→")),"Teknik numara/debug metni yok");Capture(Output+"Hint-1600.png",900,1600);
            Tap("PawCatTouch");Tap("PawHint");Check(GameplayProgress.Current.Remaining(BoosterKind.Hint)==hints-1,"Zaten gösterilen ipucundan ikinci hak düşmez");yield return new WaitForSecondsRealtime(.25f);
            GameplayProgress.UseTestProfile(new ProgressData{hint=0,completedTutorials=new List<string>{PawGuide.BasicId}});SceneManager.LoadScene("Gameplay");yield return WaitGameplay();Tap("PawCatTouch");Check(!GameObject.Find("PawHint").GetComponent<Button>().interactable,"Hak yokken öneri seçeneği devre dışı");Tap("PawHint");Check(Guide.Visible&&GameplayProgress.Current.Remaining(BoosterKind.Hint)==0&&Model.Moves==0,"Hak yokken ücretsiz ipucu üretilmez");yield return new WaitForSecondsRealtime(.25f);Capture(Output+"NoHintCharges-1600.png",900,1600);Check(Guide.HandleBack()&&!Guide.Visible,"Geri ile menü kapatılıyor");
            // Fresh profile verifies the modal menu did not regress PART11B's interactive path.
            GameplayProgress.UseTestProfile();SceneManager.LoadScene("Gameplay");yield return WaitGameplay();yield return new WaitForSecondsRealtime(.25f);Check(Guide.State==PawGuide.Phase.Welcome,"11B yeni oyuncu karşılaması korundu");Tap("PawNext");var move=Guide.Recommended;Tap("Bottle "+(move.Source+1));Check(Guide.State==PawGuide.Phase.Target,"11B kaynak seçimi eğitimde engellenmiyor");Tap("Bottle "+(move.Target+1));yield return new WaitForSecondsRealtime(1.1f);Check(Model.Moves==1&&GameplayProgress.Current.TutorialCompleted(PawGuide.BasicId),"11B gerçek hamle ve tamamlama korundu");yield return new WaitForSecondsRealtime(1.9f);Check(Guide.State==PawGuide.Phase.BoosterOffer,"11B kutlama sonrasında isteğe bağlı 11D daveti");
        }
        Rect Bounds(RectTransform r,RectTransform relative){var c=new Vector3[4];r.GetWorldCorners(c);var a=(Vector2)relative.InverseTransformPoint(c[0]);var b=(Vector2)relative.InverseTransformPoint(c[2]);return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}
        void AuditLayout(RectTransform safe,int height)
        {
            var go=GameObject.Find("PawBubble");if(go==null||safe==null)return;var rect=Bounds((RectTransform)go.transform,safe);Check(rect.xMin>=safe.rect.xMin&&rect.xMax<=safe.rect.xMax&&rect.yMin>=safe.rect.yMin&&rect.yMax<=safe.rect.yMax,"Pati balonu Safe Area içinde: "+height);
            foreach(var v in FindObjectsByType<GameplayBottleView>(FindObjectsSortMode.None))Check(!rect.Overlaps(Bounds(v.Rig,safe)),"Menü şişeyi örtmüyor: "+height);
            foreach(var t in go.GetComponentsInChildren<TMP_Text>()){t.ForceMeshUpdate();Check(!t.isTextOverflowing,"Menü metni taşmıyor: "+t.name+height);}
            var buttons=go.GetComponentsInChildren<Button>();for(int i=0;i<buttons.Length;i++){var r=(RectTransform)buttons[i].transform;Check(r.rect.width*safe.GetComponentInParent<Canvas>().scaleFactor>=44&&r.rect.height*safe.GetComponentInParent<Canvas>().scaleFactor>=44,"Menü dokunma alanı en az44px: "+buttons[i].name+height);for(int j=0;j<i;j++)Check(!Bounds(r,safe).Overlaps(Bounds((RectTransform)buttons[j].transform,safe)),"Menü butonları ayrık: "+height);}
        }
        void Capture(string filename,int width,int height,bool inset=false)
        {
            var canvas=FindFirstObjectByType<Canvas>();var camera=Camera.main;var p=FindFirstObjectByType<HomeCharacterPresenter>();var safe=p!=null?(RectTransform)p.transform.Find("UI"):(GameObject.Find("Safe area")??GameObject.Find("MapSafeArea"))?.GetComponent<RectTransform>();
            var mode=canvas.renderMode;var oldCam=canvas.worldCamera;float distance=canvas.planeDistance;var oldTarget=camera.targetTexture;var oldActive=RenderTexture.active;Vector2 min=safe!=null?safe.anchorMin:Vector2.zero,max=safe!=null?safe.anchorMax:Vector2.one;
            var rt=new RenderTexture(width,height,24);var tex=new Texture2D(width,height,TextureFormat.RGB24,false);
            try{
                camera.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;if(inset&&safe!=null){safe.anchorMin=new Vector2(.035f,.04f);safe.anchorMax=new Vector2(.965f,.955f);}
                Canvas.ForceUpdateCanvases();var gameplay=FindFirstObjectByType<GameplayPresentation>();if(gameplay!=null)gameplay.Layout();var pause=GameObject.Find("PauseSafeArea");if(pause!=null&&safe!=null){var pr=(RectTransform)pause.transform;pr.anchorMin=safe.anchorMin;pr.anchorMax=safe.anchorMax;}if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}var map=FindFirstObjectByType<Mewgic.Map.MapWorld>();if(map!=null)map.Layout();var daily=FindFirstObjectByType<Mewgic.Daily.DailyActivitiesPanel>();if(daily!=null&&daily.IsOpen)daily.Layout();var hub=FindFirstObjectByType<Mewgic.Rewards.RewardHubPanel>();if(hub!=null&&hub.IsOpen)hub.Layout();Canvas.ForceUpdateCanvases();
                foreach(var text in FindObjectsByType<TMPro.TMP_Text>(FindObjectsSortMode.None))text.ForceMeshUpdate();FindFirstObjectByType<Mewgic.UI.PawGuide>()?.SendMessage("LateUpdate");foreach(var text in FindObjectsByType<TMP_Text>(FindObjectsSortMode.None)){text.ForceMeshUpdate();if(text.name=="PawMessage")Check(!text.isTextOverflowing,"Pati balonunda taşma yok: "+height);}AuditLayout(safe,height);camera.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();File.WriteAllBytes(filename,tex.EncodeToPNG());
            }finally{camera.targetTexture=oldTarget;canvas.renderMode=mode;canvas.worldCamera=oldCam;canvas.planeDistance=distance;if(safe!=null){safe.anchorMin=min;safe.anchorMax=max;}RenderTexture.active=oldActive;DestroyImmediate(tex);rt.Release();DestroyImmediate(rt);Canvas.ForceUpdateCanvases();if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}}
        }
    }
}
